css:
    .material-symbols-outlined {
        font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 24;
    }
    .grayscale-filter {
        filter: grayscale(100%) contrast(1.1);
    }
    .card-container {
        width: 380px;
        height: 580px;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.15);
    }
    .thin-border {
        border: 0.5px solid #121c2a;
    }
    .shimmer-hologram {
        background: linear-gradient(135deg, rgba(0, 50, 125, 0.1) 0%, rgba(255, 174, 60, 0.1) 50%, rgba(0, 108, 73, 0.1) 100%);
        opacity: 0.4;
    }


body {
  min-height: max(884px, 100dvh);
}
